import React, { useContext } from "react";
import { AuthContext } from "../Context/AuthContext";

function Toolbar({ socket }) {
  const { user } = useContext(AuthContext);

  return (
    <div className="flex p-4 bg-gradient-to-r from-gray-100 to-blue-100 border-b border-gray-200 shadow-sm">
      <div className="flex items-center justify-between w-full max-w-4xl mx-auto">
        <div className="flex items-center space-x-4">
          <div className="flex items-center space-x-2 bg-white/70 backdrop-blur-sm rounded-xl px-4 py-2 shadow-lg border border-white/50">
            <div className="w-3 h-3 bg-green-400 rounded-full animate-pulse"></div>
            <span className="text-sm font-medium text-gray-700">
              Real-time collaboration active
            </span>
          </div>

          <div className="bg-white/70 backdrop-blur-sm rounded-xl px-4 py-2 shadow-lg border border-white/50">
            <span className="text-sm text-gray-600">
              <span className="font-medium">Connected as:</span> {user?.username}
            </span>
          </div>
        </div>

        <div className="flex items-center space-x-3">
          {user?.role === "admin" && (
            <div className="bg-gradient-to-r from-purple-500 to-pink-500 text-white px-4 py-2 rounded-xl shadow-lg">
              <span className="text-sm font-medium">👑 Admin Mode</span>
            </div>
          )}

          {user?.role === "editor" && (
            <div className="bg-gradient-to-r from-blue-500 to-cyan-500 text-white px-4 py-2 rounded-xl shadow-lg">
              <span className="text-sm font-medium">✏️ Editor Mode</span>
            </div>
          )}

          {user?.role === "viewer" && (
            <div className="bg-gradient-to-r from-gray-500 to-slate-500 text-white px-4 py-2 rounded-xl shadow-lg">
              <span className="text-sm font-medium">👁️ Viewer Mode</span>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default Toolbar;
